package kik.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.Callable;import java.util.function.BooleanSupplier;import org.json.*;import kik.i18n.*;
/** Pairs a disposable TV profile with a disposable web account and verifies both directions. */
public final class CloudAudit extends Instrumentation {
 Context c;String original,profile,list;Activity activity;File dir;JSONArray checks=new JSONArray();boolean passed=true;long lastPulse;
 final String link="https://hdrezka.sh/series/drama/646-vo-vse-tyazhkie-2008.html",later="https://hdrezka.sh/films/fiction/981-matrica-1999.html";
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 <T>T ui(Callable<T> f){Object[] out=new Object[2];runOnMainSync(()->{try{out[0]=f.call();}catch(Throwable t){out[1]=t;}});if(out[1]!=null)throw new RuntimeException((Throwable)out[1]);return (T)out[0];}
 Object field(Object o,String n){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 boolean await(BooleanSupplier f,long ms){long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){if(f.getAsBoolean())return true;SystemClock.sleep(250);}return false;}
 void check(String name,boolean ok)throws Exception{checks.put(new JSONObject().put("name",name).put("passed",ok));if(!ok)throw new AssertionError(name);}
 void stage(String value)throws Exception{Files.write(new File(dir,"cloud-stage").toPath(),value.getBytes("UTF-8"));}
 void save(String episode,long pos){Progress.Entry e=new Progress.Entry();e.link=link;e.title="QA Breaking Bad";e.season="1";e.episode=episode;e.voice="1";e.voiceName="QA voice";e.pos=pos;e.dur=2400000;e.observed=true;e.watchedMs=90000;Progress.save(c,e);}
 int rating()throws Exception{Class<?> cls=Class.forName("kik.i18n.RatingStore");Method m=cls.getDeclaredMethod("get",Context.class,String.class,String.class);m.setAccessible(true);return (Integer)m.invoke(null,c,profile,link);}
 @Override public void onStart(){c=getTargetContext();original=ProfileStore.current(c);list=c.getSharedPreferences("kik_profiles",0).getString("list","[]");dir=new File(c.getExternalFilesDir(null),"design-audit");dir.mkdirs();try{
  new File(dir,"cloud-finish").delete();profile=ProfileStore.create(c,"QA Cloud","CloudAudit5678").id;c.getSharedPreferences("kik_profiles",0).edit().putString("current",profile).commit();ProfileStore.picked=true;ProfileStore.completeTasteSetup(c,profile);save("1",120000);save("2",333000);Progress.toggleLater(c,later,"QA Matrix",null,"1999","Фантастика");
  Class<?> cls=Class.forName("kik.i18n.RatingStore");Method set=cls.getDeclaredMethod("set",Context.class,String.class,String.class,String.class,String.class,String.class,int.class);set.setAccessible(true);set.invoke(null,c,profile,link,"QA Breaking Bad",null,"Драма",1);
  activity=startActivitySync(new Intent(c,SyncActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{((Button)field(activity,"connect")).performClick();return null;});check("device_code_created",await(()->field(activity,"deviceCode")!=null,30000));
  JSONObject pair=new JSONObject().put("device_code",field(activity,"deviceCode")).put("user_code",ui(()->((TextView)field(activity,"code")).getText().toString().replace(" ","")));Files.write(new File(dir,"cloud-pair.json").toPath(),pair.toString().getBytes("UTF-8"));stage("pair");
  check("native_profile_authorized_from_web",await(()->CloudSync.linked(c,profile),120000));check("first_cloud_sync",await(()->CloudSync.status(c,profile).startsWith("Історію"),30000));ui(()->{activity.finish();return null;});stage("exported");
  check("web_progress_reaches_tv",await(()->{if(SystemClock.elapsedRealtime()-lastPulse>3000){lastPulse=SystemClock.elapsedRealtime();CloudSync.now(c);}long[] p=Progress.episode(c,link,"1","1");return p!=null&&p[0]==456000;},120000));check("web_deleted_episode_stays_deleted",Progress.episode(c,link,"1","2")==null);check("web_watchlist_delete_reaches_tv",!Progress.isLater(c,later));check("web_rating_reaches_tv",rating()==-1);check("latest_episode_is_web_episode",Progress.get(c,link).episode.equals("1"));
  save("1",555000);CloudSync.now(c);stage("native-updated");check("driver_verified_web_matches_tv",await(()->new File(dir,"cloud-finish").isFile(),60000));
 }catch(Throwable e){passed=false;try{checks.put(new JSONObject().put("error",e.toString()).put("cloud_status",profile==null?"":CloudSync.status(c,profile)));stage("failed");}catch(Exception ignored){}}
 finally{try{if(activity!=null&&!activity.isDestroyed())ui(()->{activity.finish();return null;});if(profile!=null){CloudSync.disconnect(c,profile);c.getSharedPreferences("kik_profiles",0).edit().putString("current",original).commit();ProfileStore.delete(c,profile);}c.getSharedPreferences("kik_profiles",0).edit().putString("list",list).putString("current",original).commit();Files.write(new File(dir,"cloud-sync.json").toPath(),new JSONObject().put("passed",passed).put("checks",checks).toString(2).getBytes("UTF-8"));if(passed)stage("complete");}catch(Exception e){passed=false;}Bundle b=new Bundle();b.putString("stream","Cloud sync audit passed="+passed+" checks="+checks.length());finish(passed?-1:0,b);}
 }
}
